import { createZodDto } from "nestjs-zod";
import { z } from "zod";

const registry = new Map<string, z.ZodType>();

/**
 * `createZodDto` plus registration under the DTO's class name. Use as
 * `class FooDto extends zodDto("FooDto", schema) {}` — the name must match the class.
 *
 * `applyZodSchemas` then replaces each DTO's OpenAPI component with JSON Schema generated by Zod
 * itself: @nestjs/swagger mangles top-level nullable fields (`string | null` came out as
 * `string[]`), which would make the generated web client lie.
 */
export function zodDto<S extends z.ZodType>(name: string, schema: S) {
  if (registry.has(name) && registry.get(name) !== schema)
    throw new Error(`Duplicate DTO name ${name}`);
  registry.set(name, schema);
  return createZodDto(schema);
}

export function applyZodSchemas<T extends { components?: { schemas?: Record<string, unknown> } }>(
  doc: T,
): T {
  const components = (doc.components ??= {});
  const schemas = (components.schemas ??= {});
  for (const [name, schema] of registry) {
    if (!(name in schemas)) continue; // DTO not referenced by any route
    const json = z.toJSONSchema(schema, {
      target: "draft-2020-12",
      io: "input",
      unrepresentable: "any",
    }) as Record<string, unknown>;
    delete json.$schema;
    schemas[name] = json;
  }
  return doc;
}
